434	        log.info("배송 상태 처리 시작: shipmentId={}, trackingNumber={}, currentStatus={}",
435	                shipmentId, trackingNumber, orderShipment.getStatus());
436	
437	        Page page = null;
438	        try {
439	
440	            page = browserManager.newPage();
441	            if (page == null) {
442	                throw new Xpb98Exception(Xpb98ErrorCode.BROWSER_INITIALIZATION_ERROR);
443	            }
444	
445	
446	            page.setDefaultTimeout(TIMEOUT_MS);
447	
448	
449	            String url = TRACKING_URL_PREFIX + trackingNumber;
450	            log.debug("배송 조회 페이지로 이동: {}", url);
451	            page.navigate(url);
452	
453	
454	            log.debug("배송 상태 테이블 로드 대기");
455	            page.waitForSelector(STATUS_SELECTOR);
456	
457	
458	            String renderedHtml = page.content();
459	            log.debug("페이지 HTML 로드 완료 (길이: {})", renderedHtml.length());
460	
461	
462	            String statusText = parseStatusFromHtml(renderedHtml, trackingNumber);
463	            Xpb98Status newStatus = mapToShipmentStatus(statusText);
464	
465	            log.debug("배송 상태 조회 결과: shipmentId={}, statusText={}, mappedStatus={}",
466	                    shipmentId, statusText, newStatus);
467	
468	
469	            if (orderShipment.getStatus() == newStatus) {
470	                log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
471	                        shipmentId, newStatus);
472	                return orderShipment;
473	            }
474	
475	
476	            if (newStatus == Xpb98Status.DELIVERED) {
477	                log.info("배송 완료 처리: shipmentId={}, orderId={}",
478	                        shipmentId, orderShipment.getOrder().getId());
479	
480	
481	                orderShipment.updateStatus(Xpb98Status.DELIVERED);
482	
483	
484	                orderService.completeOrder(orderShipment.getOrder().getId());
485	                notificationService.notifyShipmentCompleted(orderShipment.getOrder());
486	
487	            } else if (newStatus == Xpb98Status.OUT_FOR_DELIVERY) {
488	                log.info("배송 출발 처리: shipmentId={}", shipmentId);
489	                orderShipment.updateStatus(Xpb98Status.OUT_FOR_DELIVERY);
490	
491	            } else {
492	                log.info("배송 중 상태 업데이트: shipmentId={}", shipmentId);
493	                orderShipment.updateStatus(Xpb98Status.IN_TRANSIT);
494	            }
495	
496	            log.info("배송 상태 처리 완료: shipmentId={}, newStatus={}",
497	                    shipmentId, orderShipment.getStatus());
498	
499	            return orderShipment;
500	
501	        } catch (Exception e) {
502	            log.error("배송 상태 처리 중 오류 발생: shipmentId={}, trackingNumber={}, error={}",
503	                    shipmentId, trackingNumber, e.getMessage(), e);
504	
505	
506	            if (!(e instanceof Xpb98Exception)) {
507	                throw new Xpb98Exception(
508	                        Xpb98ErrorCode.EXTERNAL_TRACKING_SERVICE_ERROR,
509	                        "배송 상태 조회 중 오류 발생: " + e.getMessage(),
510	                        e
511	                );
512	            }
513	            throw e;
514	        } finally {
515	
516	            if (page != null) {
517	                try {
518	                    page.close();
519	                    log.debug("페이지 리소스 해제 완료");
520	                } catch (Exception e) {
521	                    log.warn("페이지 닫기 실패: {}", e.getMessage());
522	                }
523	            }
524	        }
525	    }
