535	    private String parseStatusFromHtml(String html, String trackingNumber) {
536	        try {
537	            Document doc = Jsoup.parse(html);
538	            Elements rows = doc.select(STATUS_SELECTOR);
539	
540	            if (rows.isEmpty()) {
541	                log.warn("배송 상태 테이블이 비어 있음: 운송장={}", trackingNumber);
542	                throw new Xpb98Exception(
543	                        Xpb98ErrorCode.TRACKING_HTML_PARSE_ERROR,
544	                        "배송 정보가 없습니다. 운송장 번호를 확인해주세요: " + trackingNumber
545	                );
546	            }
547	
548	
549	            String statusText = rows.last().select("td").get(4).text().trim();
550	
551	            if (statusText.isEmpty()) {
552	                log.warn("배송 상태 텍스트가 비어 있음: 운송장={}", trackingNumber);
553	                throw new Xpb98Exception(
554	                        Xpb98ErrorCode.TRACKING_HTML_PARSE_ERROR,
555	                        "배송 상태 정보를 찾을 수 없습니다."
556	                );
557	            }
558	
559	            return statusText;
560	
561	        } catch (IndexOutOfBoundsException e) {
562	            log.error("HTML 파싱 중 인덱스 오류: 운송장={}, 오류={}", trackingNumber, e.getMessage(), e);
563	            throw new Xpb98Exception(
564	                    Xpb98ErrorCode.TRACKING_HTML_PARSE_ERROR,
565	                    "배송 상태 정보 파싱 실패: 예상한 형식과 다릅니다.",
566	                    e
567	            );
568	        } catch (Exception e) {
569	            if (e instanceof Xpb98Exception) {
570	                throw (Xpb98Exception) e;
571	            }
572	
573	            log.error("HTML 파싱 중 오류 발생: 운송장={}, 오류={}", trackingNumber, e.getMessage(), e);
574	            throw new Xpb98Exception(
575	                    Xpb98ErrorCode.TRACKING_HTML_PARSE_ERROR,
576	                    "배송 상태 정보 파싱 실패: " + e.getMessage(),
577	                    e
578	            );
579	        }
580	    }
