588	    private Xpb98Status mapToShipmentStatus(String statusText) {
589	        return switch (statusText) {
590	            case "배송완료" -> Xpb98Status.DELIVERED;
591	            case "배송출발" -> Xpb98Status.OUT_FOR_DELIVERY;
592	            default -> Xpb98Status.IN_TRANSIT;
593	        };
594	    }
